#include "mathlink.h"

main(argc, argv)
int argc; char *argv[];
{
    MLMain(argc, argv);
}

void casteps(revrule, rlen, a, n, steps)
int *revrule, rlen, *a, n, steps;
{
    int i, *ap, t, tp;

    for (i = 0; i < steps; i++)
    {
        a[0] = a[n-2]; /* правая граница */
        a[n-1] = a[1]; /* левая граница */

        t = a[0];
        for (ap = a+1; ap <= a+n-2; ap++)
        {
            tp = ap[0];
            ap[0] = revrule[ap[1]+2*(tp + 2*t)];
            t = tp;
        }
    }

    MLPutIntegerList(stdlink, a, n);
}
